type Props = ComponentProps<typeof TitleViewDesktop>;
// tag: семантический уровень заголовка задаёт приложение.
// buttonsGroup: полный упорядоченный список реальных DS actions с callbacks/href; overflow — PickerButton, не дополнительное действие.


function Example({ tag, filterCompanySelectProps, buttonsGroup, overflowProps }: { tag: Props['tag']; filterCompanySelectProps: NonNullable<Props['filterCompanySelectProps']>; buttonsGroup: NonNullable<Props['buttonsGroup']>; overflowProps: Pick<Props, 'maxVisibleButtons' | 'pickerButtonProps'> }) {
    return <TitleViewDesktop
        tag={tag}
        view={VIEWS.XLARGE}
        showSkeleton={false}

        subtitle={"Subtitle"}
        statusProps={{  children: "Label", color: 'green', view: 'contrast', uppercase: true }}
        filterCompanySelectProps={filterCompanySelectProps}
        buttonsGroup={buttonsGroup} {...overflowProps}



    >{"Header-System 40-48"}</TitleViewDesktop>;
}

